return [{
  json: {
    status: "SKIPPED",
    decision: "SKIP",
    nextAction: "ADMIN_REVIEW",
    summary: "Pricing Agent skipped execution due to RFI/PO or invalid quantity/part number."
  }
}];

const parsed = JSON.parse($json.response);

return {
  json: {
    sessionId: parsed.sessionId || "SESS-UNKNOWN",
    sourceAgent: "Pricing_Agent",
    approvalType: "PRICING_OVERRIDE",
    title: "אישור חריגת מחירון / הצעת מחיר",
    summary: parsed.summary || `נדרש אישור מנהל עבור שינוי מחירון או הצעת מחיר חורגת.`,
    approverEmail: "ceo@company.com"
  }
};

return {
  json: {
    status: "SUCCESS",
    authorizationRequired: true,
    decision: "PRICING_APPROVED_BY_ADMIN",
    nextAction: "CONTINUE",
    summary: "שינוי המחירון / הצעת המחיר אושרה בהצלחה על ידי המנהל ב-HITL.",
    sessionId: $json.sessionId || "SESS-UNKNOWN"
  }
};

return {
  json: {
    status: "REJECTED",
    authorizationRequired: true,
    decision: "PRICING_REJECTED_BY_ADMIN",
    nextAction: "STOP",
    summary: "שינוי המחירון / הצעת המחיר נדחתה על ידי המנהל ב-HITL. העדכון לא בוצע.",
    sessionId: $json.sessionId || "SESS-UNKNOWN"
  }
};

let parsed = {};

// בדיקה בטוחה למניעת שגיאת undefined
if (typeof $json.response === 'string') {
  try {
    parsed = JSON.parse($json.response);
  } catch (e) {
    parsed = {};
  }
} else if (typeof $json.response === 'object' && $json.response !== null) {
  parsed = $json.response;
} else if (typeof $json === 'object' && $json !== null) {
  parsed = $json;
}

return {
  json: {
    ...parsed,
    status: parsed.status || "SUCCESS",
    nextAction: parsed.nextAction || "CONTINUE",
    authorizationRequired: false
  }
};
